namespace TechStore.App.Views;
public partial class MainForm:Form { readonly Dictionary<string,Form> open=[]; public MainForm(){InitializeComponent();} void Open(string key,Func<Form> factory){if(open.TryGetValue(key,out var existing)&&!existing.IsDisposed){existing.Activate();return;}var form=factory();form.MdiParent=this;form.FormClosed+=(_,_)=>open.Remove(key);open[key]=form;form.Show();} private void Menu_Click(object? sender,EventArgs e){var key=((ToolStripMenuItem)sender!).Text;switch(key){case "Inicio":Open(key,()=>new DashboardForm());break;case "Productos":case "Categorías":case "Clientes":case "Sucursales":case "Vendedores":Open(key,()=>new CrudForm(key));break;case "Inventario":Open(key,()=>new InventoryForm());break;case "Nueva venta":Open(key,()=>new SaleForm());break;case "Historial de ventas":Open(key,()=>new SalesHistoryForm());break;case "Cuentas corrientes":Open(key,()=>new AccountPaymentForm());break;case "Reportes":Open(key,()=>new ReportsForm());break;case "Salir":Close();break;}} }
